INSERT INTO fish_species (class, common_name, also_known_as, description, family, species, environmental_status, habitat, fishing_techniques, spawning_habits_lifecycle, diet_feeding_habits, water_body_type, known_for, world_record, world_record_link)
VALUES ('Salt', 'Cod, Atlantic', 'Cod, Codling, Scrod Cod, Markets, Morue, Steakers', 'Atlantic cod are heavy-bodied with a large head, blunt snout, and a distinct barbel (a whisker-like organ, like on a catfish) under the lower jaw. Their coloring varies, ranging from light yellowish-green to red and olive, usually with darker speckles on the head, fins, tail, and body. The belly is light colored and usually spotless. Individuals can change color readily. Cod have an obvious lateral line (the faint line that runs lengthwise down each side of the fish). Atlantic cod can live more than 20 years and can grow up to 51 inches and 77 pounds.', 'Gadidae', 'Gadus morhua', 'Vulnerable', 'Atlantic cod live near the ocean floor along rocky slopes and ledges. They prefer to live in cold water, at depths of around 30 to 500 feet (though they can be found in depths of up to 200 fathoms or 1200 feet).

The cod prefers rough bottoms composed of sand and rock or of shells. It is a migratory fish but the extent of its migration varies among stocks.

In the Northwest Atlantic, cod range from Greenland to Cape Hatteras, North Carolina. In U.S. waters, cod is most common on Georges Bank and in the western Gulf of Maine.', 'A highly sought after food fish, both recreationally and commercially, it would be difficult to overstate the cod’s value.

Most cod taken by anglers are caught by fishing with live or dead natural baits on the ocean bottom from a drifting or anchored boat, but many are taken by jigging and deep trolling as well. 

Cod have large mouths, so hook size may vary, but the bait need not be large—a good sized ocean clam will do for almost any size cod. Other good baits include strip baits of squid, fish, crabs, sand eels, and capelin. Artificial lures such as chrome diamond jigs, spinners, bucktails, spoons, and shiny metal squids may also be used. 

Popular techniques for catching Atlantic cod are 
bottom bouncing, saltwater jigging, still fishing, drift fishing and saltwater trolling.', 'Atlantic cod are capable of reproducing at 2 to 3 years old when they are between 12 and 16 inches long. Cod spawn near the ocean floor from winter to early spring. Larger females can produce 3 to 9 million eggs when they spawn.', 'Atlantic cod are top predators in the bottom ocean community, feeding primarily on a variety of invertebrates and fish.', 'Ocean', 'Subpar Game Qualities', '103 lb 10 oz,
Michael Eisele,
Sørøya, Norway,
4/28/2013', 'Atlantic Cod WR');

INSERT INTO fish_species (class, common_name, also_known_as, description, family, species, environmental_status, habitat, fishing_techniques, spawning_habits_lifecycle, diet_feeding_habits, water_body_type, known_for, world_record, world_record_link)
VALUES ('Salt', 'Cod, Pacific', 'Cod, Alaska Cod, Gray Cod, True Cod', 'Pacific cod are also known as gray cod because of their color—they’re brown or grayish with dark spots or patterns on the sides and a paler belly. They have a long chin barbell (a whisker-like organ near the mouth, like on a catfish) and dusky fins with white edges. Pacific cod live for 20 years or less and can grow up to 39 inches in length and weigh in at more than 33 pounds.', 'Gadidae', 'Gadus macrocephalus', 'Not Evaluated', 'Pacific Cod are found in the coastal North Pacific Ocean, from the Bering Sea to Southern California in the east and to the Sea of Japan in the west. They are less common in Central California and are rare in Southern California.

During the winter, Pacific cod live on the continental shelf edge and upper continental slope in waters 300 to more than 800 feet deep. In the summer, they move to shallower water (300 feet deep or less).

Larvae and small juveniles are found throughout the water column, while large juveniles and adults live near the ocean floor and prefer habitats of mud, sand, and clay.', 'The Pacific cod is usually caught in waters deeper than 60 ft up to 1800 ft in depth. An excellent food fish and highly rated sport fish, the Pacific cod is usually taken by anglers using whole fish or cut bait dropped on the ocean bottom from a drifting or anchored boat. 

Cod have large mouths, so hook size may vary, but the bait need not be large. Besides whole and cut bait, other good baits include strip baits of squid, fish, crabs, sand eels, and capelin. Artificial lures such as chrome diamond jigs, spinners, bucktails, spoons, and shiny metal squids may also be used.

Popular techniques for catching Atlantic cod are 
bottom bouncing, saltwater jigging, still fishing, drift fishing and saltwater trolling.', 'Pacific cod females are able to reproduce when they’re 4 or 5 years old, when they are between 1.6 and 1.9 feet long. Pacific cod spawn from January to May on the continental shelf edge and upper slope in waters 330 to 820 feet deep. Females can produce more than 1 million eggs when they spawn.', 'Pacific cod school together and move seasonally from deep outer and upper continental shelf areas (where they spawn) to shallow middle-upper continental shelf feeding grounds. They feed primarily on clams, worms, crabs, shrimp, and juvenile fish.', 'Ocean', 'Subpar Game Qualities', '38 lb 9 oz,
Atsunori Takahira,
Kawashiro, Kamoenai, Hokkaido, Japan,
1/16/2005', 'Pacific Cod WR');

INSERT INTO fish_species (class, common_name, also_known_as, description, family, species, environmental_status, habitat, fishing_techniques, spawning_habits_lifecycle, diet_feeding_habits, water_body_type, known_for, world_record, world_record_link)
VALUES ('Salt', 'Haddock', 'Scrod', 'Haddock are a member of the cod family, but they are smaller than Atlantic cod. They can be distinguished by a black “thumbprint” found on each side of their body. Their skin is also less mottled than cod. 
Haddock are a fast-growing species that typically range between 1 and 3 feet long at maturity. They can live for 10 or more years, although NOAA Fisheries scientists typically catch haddock that are between 3 and 7 years old. Haddock generally weigh between 2 and 7 pounds.', 'Gadidae', 'Melanogrammus aeglefinus', 'Vulnerable', 'Haddock are found on both sides of the North Atlantic. In the western North Atlantic, they’re found from Newfoundland to Cape May, New Jersey, and are most abundant on Georges Bank and in the Gulf of Maine.

Haddock are groundfish—they live near the bottom and prefer habitats of gravel, pebbles, clay, and smooth hard sand. These bottom types are more common on Georges Bank and as such haddock are more abundant there than in the Gulf of Maine.

Haddock are most common in waters approximately 130 to 500 feet deep and prefer temperatures below 45° F.

Juveniles are found in shallower water on bank and shoal areas, while larger adults are more common in deeper water.

Adults travel to shallower waters in the spring to spawn.', 'Anglers pursue this deep water species from private, charter or party boats.  A medium action 8 foot boat rod with a fast acting tip is recommended.  A sensitive rod is necessary to feel the light bumps the haddock creates when it grabs a baited hook.  Forty pound test monofilament line on a high speed conventional reel is recommended.  Heavy line is necessary even though the haddock is a modest sized species because anglers fishing in deep waters cannot predict what other larger fish might grab the line.
A typical haddock rig consists of the following.  A swivel (to prevent twisting) is tied to one end of a 4 foot piece of 50 pound test leader material.  A bank sinker is looped to the other end of the leader.  Number 6/0 or smaller hooks, with a short piece of yellow surge wound over their shanks are attached to the leader by two 6 to 10 inch "droppers" or loops.  Ten to 20 ounces of sinker are needed to hold the rig on the bottom, depending upon currents and depths.  A small piece of clam or squid is very successful.
After the baited rig is lowered to the bottom, all slack should be retrieved.  Unlike the cod, which gives a sharp yank, haddock bite in series of small bumps.  These slight taps can best be felt if the line is held between the thumb and finger. Because haddock have soft mouths, they are easily lost if not properly played after being hooked.  When a haddock taps the bait, the hook should be set easily with a steady pull rather than a jerk, and the fish should be steadily retrieved without pumping the rod.', 'Haddock begin to reproduce between the ages of 1 and 4 years old and at 10.5 to 11.7 inches long. They spawn between January and June on eastern Georges Bank, to the east of Nantucket Shoals and along the Maine coast over rock, gravel, sand, or mud bottoms.

Haddock are very productive. Every year, an average-sized female produces around 850,000 eggs, and larger females can produce up to 3 million eggs. Females release their eggs in batches near the ocean floor, where a courting male fertilizes them. Once fertilized, eggs rise to the surface where they drift with ocean currents. Newly hatched haddock remain near the surface for several months before they settle to the bottom.', 'Haddock feed on a variety of bottom-dwelling animals, including mollusks, worms, crustaceans, sea stars, sea urchins, sand dollars, brittle stars, and occasional fish eggs. Adults sometimes eat small fish, especially herring.

Spiny dogfish, skates, and many groundfish species (cod, pollock, cusk, hake, monkfish, halibut, and sea raven) prey on juvenile haddock. Gray seals also prey on haddock.', 'Ocean', 'Subpar Game Qualities', '14 lb 15 oz,
Ms. Heike Neblinger,
Saltraumen, Norway,
8/15/1997', 'Haddock WR');

INSERT INTO fish_species (class, common_name, also_known_as, description, family, species, environmental_status, habitat, fishing_techniques, spawning_habits_lifecycle, diet_feeding_habits, water_body_type, known_for, world_record, world_record_link)
VALUES ('Salt', 'Pollock, Alaska', 'Pollock, Walleye Pollock, Pacific Pollock', 'The Alaska pollock is a member of the cod family. They can grow as long as 3 feet but typically reach lengths between 12 and 20 inches and weigh between 1 and 3 pounds. They have speckled coloring that helps them blend in with the seafloor to avoid predators.', 'Gadidae', 'Theragra chalcogramma', 'Not Evaluated', 'Alaska pollock are found throughout the North Pacific Ocean but are most common in the Bering Sea.

Younger pollock live in the mid-water region of the ocean; older pollock (age 5 and up) typically dwell near the ocean floor.

Pollock swim in large schools in waters between 330 and 985 feet deep but are sometimes found as deep as 3,300 feet.', 'When at or near the surface, typically in spring, police are popular targets for all types of casting tackle including plugs, spinning rigs, spoons and even flies. They will go for a wide variety of each.

Best natural baits are live or cut baitfish, but they will also take standard bottom-fishing baits.', 'Alaska pollock grow fast and have a relatively short life span of about 12 years. As a result, they are generally more productive compared to slower growing, longer living species.

Some pollock begin to reproduce by the age of 3 or 4 and are extremely fertile, so each generation replaces aging or harvested fish in just a few years. In the spring, pollock migrate inshore to shallow water to breed and feed and move back to warmer, deeper waters in the winter months.', 'The survival of young pollock depends on several factors, such as the availability of food, environmental conditions, and predation. Their survival rate is highly variable, which can potentially cause large fluctuations in the abundance of pollock in a matter of a few years.

Juvenile pollock eat zooplankton (tiny floating animals) and small fish. Older pollock feed on other fish, including juvenile pollock.

Many other species—including Steller sea lions and other marine mammals, fish, and seabirds—feed on pollock and rely on them for survival.', 'Ocean', 'Fight Dynamics', '7 lb 2 oz,
Nancy L. Witherell,
Kachemak Bay, Alaska, USA,
7/4/2011', 'Alaska Pollock WR');

INSERT INTO fish_species (class, common_name, also_known_as, description, family, species, environmental_status, habitat, fishing_techniques, spawning_habits_lifecycle, diet_feeding_habits, water_body_type, known_for, world_record, world_record_link)
VALUES ('Salt', 'Pollock, Atlantic', 'Saithe, Coalfish, Coley, Green Cod, Boston Bluefish', 'Atlantic pollock are brownish-green on the back and slightly pale on the belly. They have a small chin barbel, like the whiskers on a catfish. They are a member of the cod family but can be distinguished by their greenish hue and darker flesh.

Atlantic pollock grow fast at first until they sexually mature between the ages of 3 and 6. They grow to more than 3 ½ feet long and 35 pounds and can live a long time, up to 23 years.', 'Gadidae', 'Pollachius virens', 'Not Evaluated', 'Atlantic pollock are found in the Northwest Atlantic Ocean and are most common on the western Scotian Shelf and in the Gulf of Maine.

Pollock eggs and larvae are found in the water column. Juveniles are found inshore and move offshore as they grow older. When in inshore waters, juvenile pollock school in the open water at low tide, then scatter at high tide and hide in intertidal seaweed beds.

Adults live offshore near the ocean floor over a wide variety of ocean bottom habitats including sand, mud, rocks, and vegetation.

Atlantic pollock swim in schools and are believed to travel extensively between the Scotian Shelf and Georges Bank and, to a lesser extent, between the Scotian Shelf and the Gulf of Maine.', 'When at or near the surface, typically in spring, police are popular targets for all types of casting tackle including plugs, spinning rigs, spoons and even flies. They will go for a wide variety of each.

Best natural baits are live or cut baitfish, but they will also take standard bottom-fishing baits.', 'Atlantic pollock spawn from November through February over hard, stony, or rocky ocean bottoms in areas throughout the Gulf of Maine and Georges Bank. They spawn multiple times per season. Pollock eggs rise into the water column after they are released and fertilized.', 'Smaller pollock in inshore waters feed on small crustaceans and small fish. Larger pollock mainly prey on fish.

A variety of fish eat juvenile pollock. Spiny dogfish, monkfish, and other pollock prey on adults.', 'Ocean', 'Fight Dynamics', '50 lb,
Thor-Magnus Lekang,
Salstraumen, Norway,
11/30/1995', 'Atlantic Pollock WR');

INSERT INTO fish_species (class, common_name, also_known_as, description, family, species, environmental_status, habitat, fishing_techniques, spawning_habits_lifecycle, diet_feeding_habits, water_body_type, avg_adult_weight_lbs, avg_adult_length_inches, known_for, world_record, world_record_link)
VALUES ('Salt', 'Marlin, Black', 'Bull of the Sea', 'Compared to striped or white marlins and sailfish, black marlins are more solid than their blue counterparts. They have a shorter bill and a rounder and lower dorsal fin.

Black marlin can be quickly and positively identified since it is the only marlin that have rigid pectoral fins that cannot be folded flat up against the body without breaking the joints. It is also set apart by the airfoil shape of the pectoral fins and by its very short ventral fins, which almost never exceed 12 in (30 cm) in length, regardless of the size of the fish. The first dorsal fin is proportionately the lowest of any billfish, usually less than 50 percent of the body depth. The body is laterally compressed, rather than rounded; much more so than in similar sized blue marlin.

The body is slate blue dorsally, changing abruptly to silvery white below the lateral line. When feeding or leaping, the black marlin may display light blue vertical stripes on the sides (see striped marlin coloration). Slight variations in color cause some specimens to have a silvery haze over the body. In Hawaii this has led to the name “silver marlin” (once thought to be a separate species). 

A highly rated game fish, the black marlin has the power, size, and persistence of which anglers dream. Its diet consists of squid and pelagic fishes. Fishing methods include trolling with large, whole baits (mackerel, bonito, flying fish, squid and others) or with artificial lures. Live bait is also effective. 

Though there are some exceptions, giant black marlin are larger than giant blue marlin taken on rod and reel. This may be because large black marlin are more accessible and more often occur within the range of sportfishing vessels. Blue marlin, or any marlin, larger than 300 lb (136 kg) are almost always females. A 500 lb (226.7 kg) male is a rarity', 'Istiophoridae', 'Istiompax indica
(previously Makaira indica)', 'Data Deficient', 'In addition to the Australian coast, black marlin can also be found throughout the tropical Indo-Pacific waters. They can also be found from Southern California to the Gulf of California to Chile, including the coast of all oceanic islands in between. They tend to stay in warmer waters and hunt the surface. In addition to warmer waters, they also are found close to land masses as opposed to wide-open water.', 'Many people see the black marlin as the premier game fish for sport fisherman. Because of their size and physique, these marlins are popularly fished. 

Anglers often use huge live or rigged dead baits, both skipping and swimming, to hook grander blacks, which are also taken off Hawaii, Panama and north into Mexican waters, and elsewhere.



Research off the coast of Australia suggests the large creature is much easier to catch around the full moon and the week afterwards due to its prey moving to the surface layers, which in turn forces the marlin to hunt in a wider area.', 'Age at first maturity not known. Intensive spawning occurs in the Coral Sea, especially during October and November. Water temperatures about 27–28°C during spawning.  Egg counts of ripe females totalled about 40 million', 'The Black marlin’s diet consists mostly of various fishes and cephalopods.

They preferably feed on small tuna but also prey on dolphin, cuttlefish, squid, mackerel, and large crustaceans.', 'Ocean', 1300, 192, 'Aerial Acrobatics', '1560 lb,
Alfred Glassell Jr.,
Cabo Blanco, Peru,
8/4/1953', 'Black Marlin WR');

INSERT INTO fish_species (class, common_name, also_known_as, description, family, species, environmental_status, habitat, fishing_techniques, spawning_habits_lifecycle, diet_feeding_habits, water_body_type, avg_adult_weight_lbs, avg_adult_length_inches, known_for, world_record, world_record_link)
VALUES ('Salt', 'Marlin, Blue', 'Atlantic Blue, Atlantic Blue Marlin, Grander', 'The Atlantic Blue Marlin, like other billfish, can rapidly change color, an effect created by pigment-containing iridophores and light-reflecting skin cells.

Most often, however, the body is blue-black on top with a silvery white underside. It has about 15 rows of pale, cobalt-colored stripes, each of which has round dots and/or thin bars, located on both sides of the fish. The first dorsal fin membrane is dark blue or almost black and has no dots or marks. Other fins are normally brownish-black, sometimes with a hint of dark blue. The bases of the first and second anal fins have a hint of silvery white.

The body is covered with thick, bony, elongated scales that have one, two, or three posterior points, with one being the most common form.

The bill is long and stout. Both the jaws and the palatines (the roof of the mouth) are covered with small, file-like teeth. The lateral line system is a group of neuromasts rooted in lateral line canals that can sense weak water motions and large changes in pressure. It has the appearance of a net. It is obvious in immature specimens but unclear in adults, becoming progressively embedded in the skin. The anus is just in front of the origin of the first anal fin.

The Atlantic blue marlin has two dorsal fins and two anal fins. The fins are supported by bony spines known as rays. Its first dorsal fin has 39 to 43 rays from front to back. Its second dorsal fin has six or seven rays. Its first anal fin, which is similar in shape and size to the second dorsal fin, has 13 to 16 rays, and the second anal fin has six or seven rays. The pectoral fins, which have 19 to 22 rays, are long and narrow and can be drawn in to the sides of the body. The pelvic fins are shorter than the pectorals, have a poorly developed membrane, and are depressible into ventral grooves. Its first anal fin, along with its pectoral and caudal fins, can be folded into grooves. This streamlines the fish and thereby reduces drag.

The biggest females are more than four times as heavy as the biggest males, which rarely exceed 350 lb in weight. The longest females can reach a length of 16 ft with the bill, from eye to tip, constituting about 20% of the total body length.

Body mass in the largest female specimens has been reported from 1,190 to 1,810 lb. The largest blue marlin caught by IGFA angling rules is from Vitoria, Brazil, which weighed 1,402 lb. Fishermen often refer to individual marlins that reach or exceed 1,000 pounds as "granders".', 'Istiophoridae', 'Makaira nigricans', 'Vulnerable', 'Native to the tropical and temperate waters of the Atlantic, Pacific, and Indian Oceans, blue marlins are among the most recognizable of all fish. They are cobalt-blue on top and silvery-white below, with a pronounced dorsal fin and a long, lethal, spear-shaped upper jaw.

They are so-called blue-water fish, spending most of their lives far out at sea. They are also highly migratory, and will follow warm ocean currents for hundreds and even thousands of miles.', 'Known for putting up a tremendous fight when hooked, these rare marine monsters are the holy grail for sport fishermen. Hooking and releasing a large blue marlin qualifies for many anglers as sport fishing’s greatest challenge, thrill and accomplishment. 

Sport fisherman generally troll for blue marlin using live and dead baits. Favorite baits are ballyhoo, mullet, flying fish and strip baits, but they will also take feather jigs and other artificial on occasion. 

The vast majority of all blue marlin caught are taken on commercial long lines.

Blue marlin populations are under siege primarily by (often illegal) commercial longline fishing, which is a threat to the species. 

The all-tackle record for the Atlantic is 1,402 pounds, 2 ounces, caught off Vitoria, Brazil, in 1979. For the Pacific: 1,376 pounds, taken off Kona, Hawaii, in 1982.', 'Very little is known about the spawningexternal link of blue marlins except that they are external fertilizers, open water egg scatterers, and they spawn in the eastern Atlantic during the summer. Their eggsexternal link are transparent and spherical and measure 1 mm in diameter.', 'Blue marlins prefer the higher temperature of surface waters, feeding on mackerel and tuna, but will also dive deep to eat squid. They are among the fastest fish in the ocean, and use their spears to slash through dense schools, returning to eat their stunned and wounded victims.', 'Ocean', 1600, 170, 'Aerial Acrobatics', '1402 lb 2 oz,
Paulo Amorim,
Victoria, Brazil,
2/29/1992', 'Blue Marline WR');

INSERT INTO fish_species (class, common_name, also_known_as, description, family, species, environmental_status, habitat, fishing_techniques, spawning_habits_lifecycle, diet_feeding_habits, water_body_type, known_for, world_record, world_record_link)
VALUES ('Salt', 'Marlin, Striped', 'Stripey, Striper, Spearfish, Spikefish, Marlin Rayado', 'The Striped Marlin, Kajikia audax, whose common Spanish name is marlin rayado, is a species in the family Istiophoridae, the Billfish, known as picudos in Mexico. Globally, there are only two species in the genus Kajikia, both found in Mexican waters, one in the Atlantic and one in the Pacific. This fish has very recently been placed in the Kajikia genus having formerly been known as Tetrapturus audax.

The Striped Marlins have elongated fairly compressed bodies. They are dark blue dorsally and silver ventrally with a series of fifteen cobalt colored bars made up of round dots and/or narrow bands. Their first dorsal fin is dark blue, their other fins are dark brown, and the bases of their first and second anal fins are tinged with silvery white. Their head has a prolonged slender upper bill with a rounded cross section and relatively small eyes. Their mouth is equipped with small rasp-like teeth on both jaws. They have two anal fins, the first with pointed tips and 13 to 18 rays and the second with 5 or 6 rays; both fins are very similar in size and shape to the second dorsal fin. They have two dorsal fins; the first with a long base, 37 to 42 rays, and a pointed anterior lobe that is higher in the front and gradually decreases in height toward the rear; the second with 5 or 6 rays and slightly behind the second anal fin. Their caudal fin is deeply forked. Their pectoral fins are long and narrow with pointed tips and their pelvic fins are slender and similar in size to the pectoral fins. There are two keels on the side of their tail base. Their lateral line is visible and curved over the pectoral fins and straight toward the tail base. Their body is covered with small elongated bony scales.

The World Record striped marlin was caught in the waters off New Zealand in 1986 weighing in at 494 pounds (224 kg).', 'Istiophoridae', 'Kajikia audax', 'Near Threatened', 'Striped marlin are found in tropical and warm temperate waters of the Indian and Pacific oceans, the striped marlin is pelagic and seasonally migratory, moving toward the equator during the cold season and away again during the warm season. 

Their northern distribution range extends to Oregon on the west coast of US. They are also found in the waters of California, Mexico, Mozambique, Kenya, New Zealand and Ecuador.

Striped marlin live near the water surface and mid depths of the ocean at temperatures between 65 °F and 85 °F. This species usually live in areas with plenty of forage.', 'Striped Marlin are usually located by trolling with their dorsal fin and bill often being seen cutting through the water behind the trolled bait or lure, making for an exciting visual.  

While trolling, you should scan the water for fish as they often sun themselves near the surface. When a fish is spotted you can cast a bait in front of them and hope they decide to eat it.

Most people troll rubber skirted lures when searching for Striped Marlin.  Many have had success using lures such as Zukers trolling lures in the 12” size.  

Larger bait fish such as Pacific Mackerel can be used successfully for Striped Marlin. You can wait until you see one eyeing your trolling lures and then drop a bait back.  

Always have a casting bait handy in case a fish is spotted on the surface sunning itself.  Use circle hooks for a better hookup and better release. 

Use a 65 lb braid setup when trolling and a 50 lb braid setup if pitching a bait. This usually allows for a short, but fun fight and a healthy release. A Shimano Trinidad 30 reel or a Daiwa Saltiga spinning reel would are good choices when outfitting your rig.', 'These fish are known to reproduce through the process of spawning. Their reproductive season is estimated to start around May and continue through August. They become reproductively mature when they are 4 to 6 years old. This species form groups or schools during the reproductive season. The average lifespan of the striped marlin is around 10 years.', 'These carnivorous fish are very strong predators feeding on various smaller fishes and water animals like jack mackerel, squids, sardines, anchovy, lancet fish, pilchard and tuna. They hunt in areas from close to the ocean surface down to 100 meters depth.', 'Ocean', 'Aerial Acrobatics', '494 lb,
Bill Boniface,
Tutukaka, New Zealand,
1/16/1986', 'Striped Marlin WR');

INSERT INTO fish_species (class, common_name, also_known_as, description, family, species, environmental_status, habitat, fishing_techniques, spawning_habits_lifecycle, diet_feeding_habits, water_body_type, known_for, world_record, world_record_link)
VALUES ('Salt', 'Marlin, White', 'Billfish, Broadbill, Broadbill Swordfish, Espadon, Swordfish', 'White marlin (Kajikia albidus) are large, elongated fish with a large upper jaw that forms a spear which is round in cross-section. They are dark blue to chocolate-brown in color. Although generally considered to be a rare and solitary species relative to other similar fish, white marlin occur in small groups consisting of several individuals.

This smallest of Atlantic marlins — typically 50 to 70 pounds — is found in all temperate and tropical areas, where it often comes relatively close to shore. Great jumpers, whites are particularly popular among anglers in the mid-Atlantic and Northeast states. 

Its rounded fins distinguish it readily from blue marlin — but not from the round-scale spearfish, so closely resembling white marlin that only a few years ago did scientists realize these were separate species. 

The all-tackle record white marlin weighed in at 181 pounds, 14 ounces; like the world-record blue marlin, it was caught off Vitoria, Brazil.', 'Istiophoridae', 'Kajikia albidus', 'Not Evaluated', 'White marlin are found in the Atlantic Ocean from roughly 45°N to 45°S in the southwestern Atlantic and 35°S in the southeastern Atlantic.​

Its distribution varies seasonally, reaching higher latitudes in both the northern and southern hemispheres only during the respective warm seasons. White marlin are considered oceanodromous, that is a migratory fish that migrates within the seas only.​', 'White marlin are caught many different ways. They have been caught on spreader bars, Green Machines behind a bird, horse ballyhoo-Ilander combinations, and many a white has been caught on a pin-rigged ballyhoo behind a Sea Witch. They will even occasionally be caught while chunking for tuna. These catches are a pleasant surprise but when you want to target white marlin you need to change things up a bit. Here are ten tips which will help you catch more white marlin.

Go Naked

White marlin can be caught on a variety of baits and lures. To increase your chances of hooking up, skip all of that stuff and stick with naked ballyhoo. The idea is to have a bait which the fish will want to eat and be easily processed (that means grab it and swallow it down). This also means that you should use ballyhoo on the smaller size. Rig your ballyhoo pinless. We are trying to present a bait which has as little as possible to get in the way of the fish swallowing it. That pin sticking up may hang up in just the wrong spot. You can rig your ballyhoo to skip or to swim. Both presentations work and having both in the spread is good. It has been my experience that the skipping ballyhoo will draw a lot of attention where the swimming ballyhoo just gets eaten.

Keep It Simple

There are times when putting out as many baits as you can into your trolling spread is a good thing. When targeting white marlin, less is more. Forget your 7,8,9, or 10 bait spreads. Pull 4 baits, one off of each rigger and two flat lines. When a fish comes in, it does not have too many baits to choose from and you will have a much better idea which bait it is going to eat.

Tease Them

What your trolling spread lacks without all of the fancy lures can be compensated for by pulling teasers. Pull a hookless teaser off of each outrigger in close to the boat. You can pull anything you want, something to attract attention. A classic white marlin teaser is a squid daisy chain followed by a large ballyhoo-Ilander combination. When the fish comes up to eat your teaser, take it away from him and feed him your naked ballyhoo bait. A fish all lit-up by that teaser is ready to pounce on any little fish which gets in its way.

Dredge Them Up 

The dredge is another type of teaser you really need to be using when you are targeting white marlin. Instead of working on the surface like most teasers, the dredge is designed to be pulled down under the water, out of all of the surface turbulence. The dredge mimics a bait ball, a tightly-packed school of bait fish. Dredges are made in a number of ways. They can be made with holographic strips, various artificial rubber fish, or with natural ballyhoo or mullet. You can mix them up using some natural baits and some artificial. They all look like a bait ball and they all work. Each boat will have its favorite dredge. You have to put enough weight in front of the dredge to keep it down in the water while you are trolling. You can pull your dredge from a down-rigger or you can just tie it off to a stern cleat. You need a dredge in the water and if you want, you can pull two. One from each side of the boat.

Keep Them Tight

This does not refer to you fighting the fish but keeping a tight line then is a good idea too. This is referring to your spread. Forget the way, way back stuff when targeting white marlin. Your boat is your biggest teaser, you have a teaser running off of each rigger close to the boat and you have a dredge or two under the water, just behind your boat. The action is here. Keep your baits in close where you can easily see them.

Pay Attention

This is not a fishery where you can be in a half-doze while you wait for a drag to start screaming. I have no idea how many white marlin have not been caught when a fish comes up and hits the bait and nobody notices. You need to be watching the baits and teasers so stay awake! The idea is to beat the fish to the rod. If you see a fish come up behind your right rigger bait, you want to have that rod in your hand before the fish touches the bait. Your chances for a hookup are much higher if you already have the rod in your hand when the fish bites. If he beats you to the rod, you are playing catchup.

Feed Him

When the fish tries to eat the bait, feed him or "drop back". A good drop back is a little tricky to develop. You want that bait to fall back as naturally as possible. The fish should feel no tension at all. I don''t think that a little tension actually bothers the marlin but it just makes it little more difficult for it to process the bait. Instead of it swallowing the bait and you achieving a hookup, the fish holds the bait sideways and you end up bringing back a ballyhoo head. Clickers need to be off and get your thumb off of the spool. Let the line fall from your rod tip into the water. The drop back does not need to be long but it does need to be smooth and free. With these small, naked baits, a drop back of five seconds in plenty. If you miss the fish, get your rod tip up and crank the bait back up to the surface. If you still have a ballyhoo, hold it there and be ready to drop back again. If you just have a ballyhoo head, crank it on in and get that bait out of the water.

Lighten Up

White marlin fishing is not the time to be using your 50s and 80s. Put them away and break out 20s and 30s. Light tackle will handle white marlin fine and the fish are more fun to catch on lighter tackle but this is not why you should be using the light stuff. It is just easier to catch them with light tackle. It is much easier to handle the light stuff and you can achieve a smoother, more free drop back with 20s and 30s than you can with bigger reels. Downsize your leader also. Think about 100 pound-test leader material for whites. Some captains will go down to 80 pound test. It is not that marlin are leader shy. The lighter leader allows your small baits to swim better but again it goes back to allowing the marlin to process your bait. It is easier for it to move the bait around to swallow with a lighter leader.

Not So Fast

You hook up a marlin on that little reel and the drag is screaming. You will want to clear everything and go after your fish: not so fast. There is more line on that reel than you think. White marlin tend to travel in groups. If you have hooked one, there are others around, keep trolling. The captain can help by making a turn towards whichever side your hooked fish is on. The angler moves to that side of the boat and keeps his line tight as the captain turns back towards the fish. The angler can move to the side of the boat because when fishing for white marlin, we are fishing stand-up. The fighting chair is something for you to put stuff on. While everyone is watching that white marlin jump, two more have come into your spread and nobody notices until a line pops out of a clip. It is hard to do, but the other anglers need to ignore the jumping fish and watch the other baits and teasers. When a white first comes in on a bait, an angler gets to the rod and everyone else watches to see if he is going to hook up. Everyone else needs to be looking at everything except that one bait. If you don''t raise another marlin during your turn, go ahead and clear the other lines and go get your fish.

Go To Them

Here in the mid-Atlantic, white marlin are available May through October. Our prime time, when fishing is white hot, is August through September. White marlin can pop up anywhere but during this prime time they tend to group up out in the deep. You can think of your run to your favorite yellowfin tuna areas and add another 20 miles to it. There are years when a lot of white marlin will be caught in 30 fathoms but more often the fish will be schooled up out in 500 to 1000 fathoms. To catch a lot of white marlin in the mid-Atlantic, you have to be willing to spend a lot of time overboard.

Learn to use Circle Hooks

Studies using pop-up satellite tags have shown that about 35% of white marlin caught on J-hooks will die after release. White marlin caught on circle hooks only experienced a 1.7% mortality rate.

Pitch Baits

This is a bit of a misnomer. These are not baits to cast, they are extra baits ready to be dropped back into your spread. Have two ready. One is just another naked ballyhoo white marlin set up. Having an extra rod ready can mean an extra fish when a pack of white marlin shows in your spread and you have enough anglers for one to drop back an extra bait. This rod can also be used to quickly replace that bait in the spread where you just missed that white marlin and he got your bait. He may still be there looking for another. Your second pitch bait rod is on heavier tackle and it can be a Spanish mackerel or big ballyhoo. This is for that big blue marlin which just showed up on your port teaser. He sure is rather impressive sitting there, waiting for you to feed him something. Get that pitch bait out!', 'The life cycle of K. albidus begins with a large spawning in warm tropical waters near the equator. Researchers have assessed that each female can lay 190,000 to 586,000 eggs. The Gulf of Mexico, Mona Passage, Southwest Bermuda, and Northwest Grand Bahama Island are few location have been located as prime spawning ground for white marlin. White marlin return to the warm shallow equatorial waters each year to spawn for the new generation. Growth of white marlin is very rapid, with males reaching sexual maturity at only 153.2 cm LJFL and females becoming sexually mature at 189.9 cm LJFL. The lifespan of white marlin has been identified as 15 or more years.', 'White marlin are near the top of the food chain and will consume anything they can find that is manageable for their size. Schooling flyingfish, small tuna, mahi-mahi, and squid are the preferred prey of white marlin. White marlin have two ways of foraging for food. One way white marlin obtain food is by help of other predators. White marlin usually keep to themselves but will socialize with other apex predators in order to increase the efficiency of foraging. Another way white marlin obtain food is by diving down in a V- or U- shaped parabola to about 200 m in search for food that is not at the surface. In order to survive in these lower temperatures and darker environments, white marlin have evolved to have larger eyes and a way to selectively warm their eye and brain tissue.', 'Ocean', 'Aerial Acrobatics', '181 lb 14 oz,
Evandro Coser,
Vitoria, Brazil,
12/8/1979', 'White Marlin WR');

INSERT INTO fish_species (class, common_name, also_known_as, description, family, species, environmental_status, habitat, fishing_techniques, spawning_habits_lifecycle, diet_feeding_habits, water_body_type, avg_adult_weight_lbs, avg_adult_length_inches, known_for, world_record, world_record_link)
VALUES ('Salt', 'Sailfish, Atlantic', 'Bayonetfish, Billfish, Indo-Pacific Sailfish, Ocean Gar, Ocean Guard, Pacific Sailfish, Sailfish, Spindlebeack', 'The Atlantic sailfish (Istiophorus albicans) is a species of marine fish in the family Istiophoridae of the order Perciformes. It is found in the Atlantic Oceans and the Caribbean Sea, except for large areas of the central North Atlantic and the central South Atlantic, from the surface to depths of 200 m (656 ft). The Atlantic sailfish is related to the marlin.

Although present taxonomy suggests that the Atlantic and Pacific sailfishes are of the same species, it is probable that there at least three, including and Indo-Pacific form. For practical purposes the Atlantic and Pacific sailfishes are treated separately.

Tests in the 1920s estimated that the Atlantic sailfish was capable of short sprints of up to 111 kilometres per hour; however, more conservative estimates of 37 to 55 kilometres per hour are more widely accepted.

Atlantic sailfish hunt schooling fish, such as sardines, anchovies and mackerel although they also feed on crustaceans and cephalopods.

The Atlantic sailfish is a metallic blue fish with a large sail-like dorsal fin and a long and pointed bill-like snout. It is dark bluish-black on the upperparts and lighter on the sides (counter-shading), with about twenty bluish horizontal bars along the flanks; the underparts are silvery white. The tail fin is strongly forked. The fins are bluish-black and the front dorsal fin is speckled with small black spots. The bases of the anal fins are pale.

The length of this fish is up to 3.15 m (10.3 ft) and the maximum published weight is 58.1 kg (128.1 lb).', 'Istiophoridae', 'Istiophorus platypterus', 'Least Concern', 'The Atlantic sailfish is a pelagic fish of tropical and temperate waters in the Atlantic Ocean. It ranges from approximately 40°N in the northwestern Atlantic to 40°S in the southwestern Atlantic, and 50°N in the northeastern Atlantic to 32°S in the southeastern Atlantic. 

It is a migratory species and moves about the open ocean and into the Mediterranean Sea. Its depth range is from warm surface waters down to about 200 m (656 ft). There is evidence that it also swims into deeper water. It is less oceanic than other billfishes, making frequent forays into nearshore water.', 'The Atlantic Sailfish is highly prized by anglers around the world due to its outstanding sporting characteristics. Its fighting ability and spectacular aerial acrobatics endear the sailfish to the saltwater angler, but it tires quickly and is considered a light tackle species. 

The most action is found where sailfish are located on or near the surface where they feed. 

The favorite method for landing Atlantic Sailfish is trolling, using a strip of tuna belly, or a whole mullet, or ballyhoo for bait as well as live bait fishing and kite fishing. 

Sometimes sailfish will take feathers or spoons. A few sailfish may be caught incidental to tuna fishing operations, but the meat tends to be tough, although tasty, and is of little commercial value except when smoked.

The most action is found where sailfish are located on or near the surface where they feed.', 'Spawning of the sailfish occurs chiefly in the summer, but may begin as early as April and extend well into the fall. The eggs are about 0.85 millimeters in diameter with large females laying more than 4.5M eggs. 

Development appears to be very rapid, with the result that you sailfish may reach a weight of about six pounds in as many months. At this weight, they are about 4.5 feet long. Subsequently, growth in length slows down, while the weight continues to increase. 

Along the Atlantic Coast of the United States, sailfish undertake regular seasonal movements. There appears to be a center of abundance off the coast of Florida, where some fish remain year round.

In the spring, large numbers of sailfish tend to move northward from this area as the water warms.

The Atlantic Sailfish school up and swim southward again as soon as the cold north winds start blowing in the fall.', 'Schooling fish such as sardines, anchovies and mackerel athough they also feed on crustaceans and cephalopods.', 'Ocean', 128, 120, 'Aerial Acrobatics', '142 lb 6 oz,
Marco Couto,
Lobito, Angola,
3/12/2014', 'Atlantic Sailfish WR');
